import{_ as p,a0 as l,w as o,s as n,ao as h,I as d,x as s,a1 as a,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"LFCS 基础：sed 命令 | LCTT x X-CMD","titleTemplate":false,"description":"LFCS 基础：sed 命令 | LCTT (201710) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"LFCS 基础：sed 命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"LFCS 基础：sed 命令 | LCTT (201710) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201710/20170529 LFCS sed Command","title":"LFCS 基础：sed 命令","tag":"201710","desc":""},"relativePath":"201710/20170529 LFCS sed Command.md","filePath":"[post].md"}'),r={name:"201710/20170529 LFCS sed Command.md"};function c(g,e,k,b,u,f){const i=l("Link");return o(),n("div",null,[e[13]||(e[13]=h(`<h1 id="lfcs-基础-sed-命令" tabindex="-1">LFCS 基础：sed 命令 <a class="header-anchor" href="#lfcs-基础-sed-命令" aria-label="Permalink to “LFCS 基础：sed 命令”">​</a></h1><p>Linux 基金会认证系统管理员（LFCS）的另一个有用的命令是 “sed”，最初表示“流式编辑器” （Streaming EDitor）。</p><p>“sed” 命令是一个可以将文件作为流进行编辑的编辑器。流式传输文件的方法是从另一个命令使用管道（<code>&gt;</code> 或 <code>|</code>）传递，或将其直接加载到 “sed” 中。</p><p>该命令的工作方式与其他编辑器相同，只是文件不显示，也不允许可视化编辑。命令被传递给 “sed” 来操纵流。</p><p>用 “sed” 可以做五件基本的事。当然，“sed” 如此强大，还有其他高级的功能，但你只需要集中精力在五件基本的事上。五种功能类型如下：</p><ol><li>搜索</li><li>替换</li><li>删除</li><li>添加</li><li>改变/变换</li></ol><p>在深入命令参数之前，我们需要看看基本的语法。</p><h3 id="语法" tabindex="-1">语法 <a class="header-anchor" href="#语法" aria-label="Permalink to “语法”">​</a></h3><p>“sed” 命令的语法是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sed [选项] 命令 [要编辑的文件]</span></span></code></pre></div><p>本文将在适当的部分中介绍这些“选项”。“命令”可以是正则表达式的搜索和替换模式。请继续阅读了解 “sed” 如何工作的并学习基本命令。正如我之前提到的，“sed” 是一个非常强大的工具，有更多的选项可用，我将在本文中介绍。</p><h3 id="示例文件" tabindex="-1">示例文件 <a class="header-anchor" href="#示例文件" aria-label="Permalink to “示例文件”">​</a></h3><p>如果你打开一个终端，那你可以创建一个用于 “sed” 示例的文件。执行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cd ~</span></span>
<span class="line"><span>grep --help &gt;grephelp.txt</span></span></code></pre></div><p>你现在应该在 HOME 文件夹中有一个名为 <code>grephelp.txt</code> 的文件。该文件的内容是 <code>grep</code> 命令的帮助说明。</p><h3 id="搜索" tabindex="-1">搜索 <a class="header-anchor" href="#搜索" aria-label="Permalink to “搜索”">​</a></h3><p>搜索特定字符串是编辑器的常见功能，在 “sed” 中执行搜索也不例外。</p><p>执行搜索以在文件中查找字符串。我们来看一下基本的搜索。</p><p>如果我们想在示例文件搜索 <code>PATTERN</code> 这个词，我们将使用如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sed -n &#39;s/PATTERN/PATTERN/p&#39; grephelp.txt</span></span></code></pre></div><p><strong>注意：</strong> 如果剪切粘贴命令，请确保将单引号替换为键盘上的标准单引号。</p><p>参数 <code>-n</code> 用于抑制每行的自动打印（除了用 <code>p</code> 命令指定的行）。默认情况下，流入 “sed” 的每一行将被打印到标准输出（stdout）。如果你不使用 “-n” 选项运行上述命令，你将看到原始文件的每一行以及匹配的行。</p><p>要搜索的文件名是我们在“示例文件”部分中创建的 “grephelp.txt”。</p><p>剩下的部分是 <code>&#39;s/PATTERN/PATTERN/p&#39;</code> 。这一段基本分为四个部分。第一部分的 <code>s</code> 指定执行替换，或搜索并替换。</p><p>剩下的第二部分和第三部分是模式。第一个是要搜索的模式，最后一个是替换流中匹配字符串的模式。此例中，我们找到字符串 <code>PATTERN</code>，并用 <code>PATTERN</code> 替换。通过查找和替换相同的字符串，我们完全不会更改文件，甚至在屏幕上也一样。</p><p>最后一个命令是 <code>p</code>。 它指定在替换后打印新行。当然，因为替换的是相同的字符串，所以没有改变。由于我们使用 <code>-n</code> 参数抑制打印行，所以更改的行将使用 <code>p</code> 命令打印。</p><p>这个完整的命令允许我们执行搜索并查看匹配的结果。</p><h3 id="替换" tabindex="-1">替换 <a class="header-anchor" href="#替换" aria-label="Permalink to “替换”">​</a></h3><p>当搜索特定字符串时，你可能希望用匹配的字符串替换新字符串。用另一个字符串替换是很常见的操作。</p><p>我们可以使用以下命令执行相同的搜索：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sed -n &#39;s/PATTERN/Pattern/p&#39; grephelp.txt</span></span></code></pre></div><p>在这时，字符串 “PATTERN” 变为 “Pattern” 并显示。如果你使用命令 <code>cat grephelp.txt</code> 查看文件，你会看到该文件没有更改。该更改仅对屏幕上的输出进行。你可以使用以下命令将输出通过管道传输到另一个文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sed &#39;s/PATTERN/Pattern/&#39; grephelp.txt &gt; grephelp1.txt</span></span></code></pre></div><p>现在将存在一个名为 <code>grephelp1.txt</code> 的新文件，其中保存了更改的文件。如果 <code>p</code> 作为第四个选项留下，那么有个问题是被替换的字符串的每一行将在文件中重复两次。我们也可以删除 “-n” 参数以允许所有的行打印。</p><p>使用相同字符串替换字符串的另一种方法是使用 <code>&amp;</code> 符号来表示搜索字符串。例如，命令 <code>s/PATTERN/&amp;/p</code> 效果是一样的。我们可以添加字符串，例如添加 <code>S</code>，可以使用命令 <code>s/PATTERN/&amp;S/p</code>。</p><p>如果我们希望在每一行中只替换某种模式呢？可以指定要替换的匹配项的特定出现。当然，每一行的替换都是一个特定的编号。例如，示例文件上有很多破折号。一些行至少有两条破折号，所以我们可以用另一个字符代替每一行的第二个破折号。每行用星号 <code>*</code> 替换第二个破折号 <code>-</code> 的命令将是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sed &#39;s/-/*/2&#39; grephelp.txt</span></span></code></pre></div><p>在这里，我们用最初的 <code>s</code> 来执行替换。字符 <code>-</code> 被替换为 <code>*</code>。<code>2</code> 表示我们想要替换每行上的第二个 <code>-</code>（如果存在）。如果我们忽略了命令 <code>2</code>，则替换第一次出现的破折号。只有第一个破折号而不是每行的破折号都被替换。</p><p>如果要搜索并替换带有星号的行上的所有破折号，请使用 <code>g</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sed &#39;s/-/*/g&#39; grephelp.txt</span></span></code></pre></div><p>命令也可以组合。假设你想要替换从第二次开始出现的破折号，命令将是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sed &#39;s/-/*/2g&#39; grephelp.txt</span></span></code></pre></div><p>现在从第二个开始出现的破折号将被星号取代。</p><h3 id="删除" tabindex="-1">删除 <a class="header-anchor" href="#删除" aria-label="Permalink to “删除”">​</a></h3><p>搜索过程中有很多时候你可能想要完全删除搜索字符串。</p><p>例如，如果要从文件中删除所有破折号，你可以使用以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sed &#39;s/-//g&#39; grephelp.txt</span></span></code></pre></div><p>替换字符串为空白，因此匹配的字符串将被删除。</p><h3 id="添加" tabindex="-1">添加 <a class="header-anchor" href="#添加" aria-label="Permalink to “添加”">​</a></h3><p>当找到匹配时，你可以添加一行特定的文本，来使这行在浏览或打印中突出。</p><p>如果要在匹配后插入新行，那么使用 <code>a</code> 命令，后面跟上新行的字符串。还包括要匹配的字符串。例如，我们可以找到一个 <code>--</code>，并在匹配的行之后添加一行。新行的字符串将是 <code>double dash before this line</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sed &#39;/--/ a &quot;double dash before this line&quot;&#39; grephelp.txt</span></span></code></pre></div><p>如果要在包含匹配字符串的行之前加上这行，请使用 <code>i</code> 命令，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sed &#39;/--/ i &quot;double dash after this line&quot;&#39; grephelp.txt</span></span></code></pre></div><h3 id="改变-变换" tabindex="-1">改变/变换 <a class="header-anchor" href="#改变-变换" aria-label="Permalink to “改变/变换”">​</a></h3><p>如果需要改变/变换一行，则可以使用命令 <code>c</code>。</p><p>假设我们有个有一些私人信息的文档，我们需要更改包含特定字符串的行。<code>c</code> 命令将改变整行，而不仅仅是搜索字符串。</p><p>假设我们想要阻止示例文件中包含单词 <code>PATTERN</code> 的每一行。更改的行将显示为 <code>This line is Top Secret</code>。命令是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sed &#39;/PATTERN/ c This line is Top Secret&#39; grephelp.txt</span></span></code></pre></div><p>可以进行更改特定字母的大小写的转换。例如，我们可以使用命令 <code>y</code> 将所有小写 <code>a</code> 更改为大写 <code>A</code>，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sed &#39;y/a/A/&#39; grephelp.txt</span></span></code></pre></div><p>可以指定多个字母，如 <code>abdg</code>，如下命令所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sed &#39;y/abdg/ABDG/&#39; grephelp.txt</span></span></code></pre></div><p>确保第二组字母与第一组字母的顺序相同，否则会被替换和转换。例如，字符串 <code>y/a/D/</code> 将用大写 <code>D</code> 替换所有小写的 <code>a</code>。</p><h3 id="就地更改" tabindex="-1">就地更改 <a class="header-anchor" href="#就地更改" aria-label="Permalink to “就地更改”">​</a></h3><p>如果你确实要更改所使用的文件，请使用 <code>-i</code> 选项。</p><p>例如，要将 <code>PATTERN</code> 改为 <code>Pattern</code>，并对文件进行更改，则命令为：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sed -i &#39;s/PATTERN/Pattern/&#39; grephelp.txt</span></span></code></pre></div><p>现在文件 <code>grephelp.txt</code> 将被更改。<code>-i</code> 选项可以与上述任何命令一起使用来更改原始文件的内容。</p><p>练习这些命令，并确保你理解它们。“sed” 命令非常强大。</p><hr>`,71)),d("p",null,[e[1]||(e[1]=s("via: ",-1)),a(i,{href:"https://www.linux.org/threads/lfcs-sed-command.4561/"},{default:t(()=>[...e[0]||(e[0]=[s("https://www.linux.org/threads/lfcs-sed-command.4561/",-1)])]),_:1})]),d("p",null,[e[5]||(e[5]=s("作者：",-1)),a(i,{href:"https://www.linux.org/threads/lfcs-sed-command.4561/"},{default:t(()=>[...e[2]||(e[2]=[s("Jarret B",-1)])]),_:1}),e[6]||(e[6]=s(" 译者：",-1)),a(i,{href:"https://github.com/geekpi"},{default:t(()=>[...e[3]||(e[3]=[s("geekpi",-1)])]),_:1}),e[7]||(e[7]=s(" 校对：",-1)),a(i,{href:"https://github.com/wxy"},{default:t(()=>[...e[4]||(e[4]=[s("wxy",-1)])]),_:1})]),d("p",null,[e[10]||(e[10]=s("本文由 ",-1)),a(i,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...e[8]||(e[8]=[s("LCTT",-1)])]),_:1}),e[11]||(e[11]=s(" 原创编译，",-1)),a(i,{href:"https://linux.cn/"},{default:t(()=>[...e[9]||(e[9]=[s("Linux中国",-1)])]),_:1}),e[12]||(e[12]=s(" 荣誉推出",-1))])])}const T=p(r,[["render",c]]);export{x as __pageData,T as default};
